import{_ as l,o as e,c as i,ag as o}from"./chunks/framework.C5oN-8Wt.js";const c=JSON.parse('{"title":"v0.1.0-alpha 模块教学文档","description":"","frontmatter":{},"headers":[],"relativePath":"v0.1.0-alpha/index.md","filePath":"v0.1.0-alpha/index.md"}'),r={name:"v0.1.0-alpha/index.md"};function s(d,a,h,t,m,n){return e(),i("div",null,[...a[0]||(a[0]=[o('<h1 id="v0-1-0-alpha-模块教学文档" tabindex="-1">v0.1.0-alpha 模块教学文档 <a class="header-anchor" href="#v0-1-0-alpha-模块教学文档" aria-label="Permalink to &quot;v0.1.0-alpha 模块教学文档&quot;">​</a></h1><p>已发布版本。适用 GNU Radio 3.10.12.0。</p><p>从左侧目录选择模块，先看接线和观察方法，再按参数表调整实验。文章按模块类型编写，同一类型的多个实例共用。</p><h2 id="先做一次实验" tabindex="-1">先做一次实验 <a class="header-anchor" href="#先做一次实验" aria-label="Permalink to &quot;先做一次实验&quot;">​</a></h2><ol><li>从模块文章下载 <code>.cnsproj</code>，在 Master 的“文件 → 打开工程”载入。</li><li>从“编辑 → 插入”打开观察器，在参数页选择文章指定的输出。</li><li>按 <strong>F5</strong> 运行；<strong>Ctrl+F5</strong> 只准备，<strong>Shift+F5</strong> 停止当前本地任务。</li><li>保存工程会保留图和参数；重新打开不会恢复样本或运行进程。</li></ol><p>本站示例均为 <strong>PC 本地仿真</strong>。阅读网站需要网络，本地实验无需登录或联网。</p><h2 id="如何读参数表" tabindex="-1">如何读参数表 <a class="header-anchor" href="#如何读参数表" aria-label="Permalink to &quot;如何读参数表&quot;">​</a></h2><p>表中默认值是内置默认，不会覆盖你的本机设置或已有工程。“可在线应用”须显式应用并查看节点回执；其余字段先停止、重新准备。同组参数、端口类型和实际采样率须满足文章说明的关联约束。</p><p><code>numeric_f64</code> / <code>complex_f64</code> 是 Master 通道标识；当前 GNU 原生浮点流分别为 float32 / complex64。整数和 byte 保留原生宽度。向量的一个 item 含 vlen 个分量，采样率和样本数按 item 计算；数值工具须显式选择分量。</p><h2 id="频谱怎么读" tabindex="-1">频谱怎么读 <a class="header-anchor" href="#频谱怎么读" aria-label="Permalink to &quot;频谱怎么读&quot;">​</a></h2><p>本版本使用 1024 点周期 Hann 窗、无重叠，只为完整窗口生成频谱。实数给出 DC 至奈奎斯特的单边线性峰值谱；复数是移频双边谱，不乘实数单边系数。频率、幅值和时间以实际帧为准，未满一窗的尾段不补零。码元索引不生成模拟幅度频谱。</p><h2 id="模块目录" tabindex="-1">模块目录 <a class="header-anchor" href="#模块目录" aria-label="Permalink to &quot;模块目录&quot;">​</a></h2><ul><li><a href="./modules/signal_source/">信号源</a></li><li><a href="./modules/noise_source/">噪声源</a></li><li><a href="./modules/add/">加法器</a></li><li><a href="./modules/low_pass/">低通滤波器</a></li><li><a href="./modules/multiply/">乘法器</a></li><li><a href="./modules/gain/">增益器</a></li><li><a href="./modules/delay/">延时器</a></li><li><a href="./modules/high_pass/">高通滤波器</a></li><li><a href="./modules/band_pass/">带通滤波器</a></li><li><a href="./modules/fir/">FIR 滤波器</a></li><li><a href="./modules/complex_signal_source/">复数信号源</a></li><li><a href="./modules/complex_noise_source/">复数噪声源</a></li><li><a href="./modules/complex_add/">复数加法器</a></li><li><a href="./modules/complex_low_pass/">复数低通滤波器</a></li><li><a href="./modules/complex_multiply/">复数乘法器</a></li><li><a href="./modules/complex_gain/">复数增益器</a></li><li><a href="./modules/complex_delay/">复数延时器</a></li><li><a href="./modules/complex_high_pass/">复数高通滤波器</a></li><li><a href="./modules/complex_band_pass/">复数带通滤波器</a></li><li><a href="./modules/complex_fir/">复数FIR 滤波器</a></li><li><a href="./modules/iq_combine/">I/Q 合成器</a></li><li><a href="./modules/iq_split/">I/Q 分解器</a></li><li><a href="./modules/random_symbols/">随机码元发生器</a></li><li><a href="./modules/symbol_mapper/">符号映射器</a></li><li><a href="./modules/symbol_slicer/">符号判决器</a></li><li><a href="./modules/channel_model/">信道模拟器</a></li><li><a href="./modules/vector_source/">向量点表源</a></li></ul>',13)])])}const u=l(r,[["render",s]]);export{c as __pageData,u as default};
